      "name": "Polynomial.eval₂_sub",
      "module_name": "Mathlib.Algebra.Polynomial.Eval.Defs",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] {p q : Polynomial R} {S : Type u_1} [inst_1 : Ring S] (f : R →+* S) {x : S},\n  Polynomial.eval₂ f x (p - q) = Polynomial.eval₂ f x p - Polynomial.eval₂ f x q"
    },
    {
      "name": "MvPolynomial.bind₁",
      "module_name": "Mathlib.Algebra.MvPolynomial.Monad",
